1	import type { Request, Response, NextFunction } from "express";
2	import { getAuth, clerkClient } from "@clerk/express";
3	import { db } from "@workspace/db";
4	import { userRolesTable } from "@workspace/db/schema";
5	import { eq } from "drizzle-orm";
6	import { timingSafeEqual } from "node:crypto";
7	import type { UserRole } from "@workspace/db/schema";
8	
9	/**
10	 * Test-only auth bypass. If AGENT_BYPASS_KEY is set in env AND a request carries
11	 * `x-replit-agent-auth: <that key>`, requireAuth/requireOwner/requireCoach/
12	 * requireAdmin all let the request through. The caller can also provide:
13	 *   x-replit-agent-userid: <clerk-user-id>   (the userId getCurrentUserId returns)
14	 *   x-replit-agent-role:   <admin|owner|coach|player>   (the role getUserRole returns)
15	 * If those headers are omitted, defaults are 'agent-test-user' and 'admin'.
16	 *
17	 * The bypass is a no-op when AGENT_BYPASS_KEY is unset, so production safety is
18	 * preserved as long as that secret is never set in the production environment.
19	 */
20	function isAgentBypass(req: Request): boolean {
21	  const expected = process.env.AGENT_BYPASS_KEY;
22	  if (!expected) return false;
23	  const provided = req.header("x-replit-agent-auth");
24	  if (!provided) return false;
25	  const a = Buffer.from(expected);
26	  const b = Buffer.from(provided);
27	  if (a.length !== b.length) return false;
28	  return timingSafeEqual(a, b);
29	}
30	
31	function bypassUserId(req: Request): string {
32	  return req.header("x-replit-agent-userid") || "agent-test-user";
33	}
34	
35	function bypassRole(req: Request): UserRole {
36	  const r = req.header("x-replit-agent-role");
37	  if (r === "admin" || r === "owner" || r === "coach" || r === "player") return r;
38	  return "admin";
39	}
