218	/** Express middleware: requires role in {admin, owner, coach} — used for tournament organizers. */
219	export async function requireCreator(req: Request, res: Response, next: NextFunction): Promise<void> {
220	  try {
221	    if (isAgentBypass(req)) {
222	      const r = bypassRole(req);
223	      if (r === "admin" || r === "owner" || r === "coach") { applyBypassToReq(req); next(); return; }
224	      res.status(403).json({ error: "Tik aikštynų savininkai ir treneriai gali organizuoti turnyrus." });
225	      return;
226	    }
227	    const { userId } = getAuth(req);
228	    if (!userId) {
229	      res.status(401).json({ error: "Unauthorized" });
230	      return;
231	    }
232	    const role = await getUserRole(userId);
233	    if (role !== "admin" && role !== "owner" && role !== "coach") {
234	      res.status(403).json({ error: "Tik aikštynų savininkai ir treneriai gali organizuoti turnyrus." });
235	      return;
236	    }
237	    next();
238	  } catch (err) {
239	    next(err);
240	  }
241	}
