46	// Booking `date`/`startTime` are stored as Lithuanian local time strings. The
47	// server runs in UTC, so naively parsing `${date}T${startTime}:00` would treat
48	// them as UTC and give a result that is wrong by Vilnius's DST offset (2–3h).
49	// Compute the UTC instant for the Vilnius wall-clock time, then diff against
50	// `Date.now()` in absolute milliseconds.
51	export function vilniusLocalToUtcMs(date: string, time: string): number {
52	  const dateOnly = String(date).slice(0, 10);
53	  // Step 1: pretend the local string is UTC.
54	  const naiveUtcMs = Date.parse(`${dateOnly}T${time}:00Z`);
55	  // Step 2: ask what Europe/Vilnius wall-clock that UTC instant displays.
56	  const fmt = new Intl.DateTimeFormat("en-GB", {
57	    timeZone: "Europe/Vilnius",
58	    year: "numeric", month: "2-digit", day: "2-digit",
59	    hour: "2-digit", minute: "2-digit", second: "2-digit",
60	    hour12: false,
61	  });
62	  const parts = fmt.formatToParts(new Date(naiveUtcMs));
63	  const get = (t: string) => parts.find(p => p.type === t)!.value;
64	  let hh = get("hour");
65	  if (hh === "24") hh = "00";
66	  const vilniusAsUtcMs = Date.UTC(
67	    Number(get("year")), Number(get("month")) - 1, Number(get("day")),
68	    Number(hh), Number(get("minute")), Number(get("second")),
69	  );
70	  // Offset = how many ms Vilnius is AHEAD of UTC at that instant (+2h or +3h).
71	  const offsetMs = vilniusAsUtcMs - naiveUtcMs;
72	  // Subtract offset to get the actual UTC instant for that Vilnius wall-clock time.
73	  return naiveUtcMs - offsetMs;
74	}
75	
76	export function hoursBeforeStart(date: string, startTime: string): number {
77	  return (vilniusLocalToUtcMs(date, startTime) - Date.now()) / (1000 * 60 * 60);
78	}
79	
80	function toMin(t: string): number {
81	  const [h, m] = t.split(":").map(Number);
82	  return h * 60 + m;
83	}
84	
85	function slotsBetween(startTime: string, endTime: string): string[] {
86	  const start = toMin(startTime);
87	  const end = toMin(endTime);
88	  const result: string[] = [];
89	  for (let m = start; m < end; m += 30) {
90	    const h = Math.floor(m / 60);
91	    const min = m % 60;
92	    result.push(`${h.toString().padStart(2, "0")}:${min.toString().padStart(2, "0")}`);
93	  }
94	  return result;
95	}
