99	function formatBooking(booking: typeof bookingsTable.$inferSelect, courtName?: string) {
100	  return {
101	    ...booking,
102	    totalPrice: Number(booking.totalPrice),
103	    refundAmount: Number(booking.refundAmount ?? 0),
104	    pricePerSlot: booking.pricePerSlot != null ? Number(booking.pricePerSlot) : undefined,
105	    totalSlots: booking.totalSlots ?? undefined,
106	    splitInviteToken: booking.splitInviteToken ?? undefined,
107	    rentedItems: booking.rentedItems ?? undefined,
108	    courtName: courtName ?? undefined,
109	    stripeSessionId: booking.stripeSessionId ?? undefined,
110	    stripePaymentIntentId: booking.stripePaymentIntentId ?? undefined,
111	    stripeRefundId: booking.stripeRefundId ?? undefined,
112	    managementToken: booking.managementToken ?? undefined,
113	  };
