116	router.get("/bookings", requireAuth, async (req, res): Promise<void> => {
117	  const params = ListBookingsQueryParams.safeParse(req.query);
118	  if (!params.success) {
119	    res.status(400).json({ error: params.error.message });
120	    return;
121	  }
122	
123	  const userId = getCurrentUserId(req)!;
124	  const role = await getUserRole(userId);
125	
126	  const conditions = [];
127	  if (params.data.courtId != null) {
128	    conditions.push(eq(bookingsTable.courtId, params.data.courtId));
129	  }
130	  if (params.data.status) {
131	    conditions.push(eq(bookingsTable.status, params.data.status));
132	  }
133	  if (params.data.customerEmail) {
134	    conditions.push(eq(bookingsTable.customerEmail, params.data.customerEmail));
135	  }
136	
137	  let query = db
138	    .select({
139	      booking: bookingsTable,
140	      courtName: courtsTable.name,
141	    })
142	    .from(bookingsTable)
143	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
144	    .$dynamic();
145	
146	  if (role === "admin") {
147	    if (conditions.length > 0) {
148	      query = query.where(and(...conditions));
149	    }
150	  } else {
151	    // "My bookings" — always scoped to the authenticated booker, regardless of
152	    // role. Owners use GET /api/owner/bookings for the facility-wide view.
153	    conditions.push(eq(bookingsTable.bookerUserId, userId));
154	    query = query.where(and(...conditions));
155	  }
156	
157	  const rows = await query;
158	  res.json(ListBookingsResponse.parse(rows.map(r => formatBooking(r.booking, r.courtName ?? undefined))));
159	});
