1006	    if (scoreTeamA === undefined || scoreTeamB === undefined) {
1007	      res.status(400).json({ error: "scoreTeamA and scoreTeamB required" }); return;
1008	    }
1009	    teamAScore = Number(scoreTeamA);
1010	    teamBScore = Number(scoreTeamB);
1011	    if (
1012	      !Number.isFinite(teamAScore) || !Number.isFinite(teamBScore) ||
1013	      !Number.isInteger(teamAScore) || !Number.isInteger(teamBScore) ||
1014	      teamAScore < 0 || teamBScore < 0
