1629	export async function applyResultElo(gameResultId: number): Promise<void> {
1630	  const [result] = await db.select().from(gameResultsTable).where(eq(gameResultsTable.id, gameResultId));
1631	  if (!result) return;
1632	  if (result.status === "confirmed") return; // idempotent
1633	
1634	  // Only the FIRST caller flips status (race between /verify-confirm and cron).
1635	  const flipped = await db
1636	    .update(gameResultsTable)
1637	    .set({ status: "confirmed" })
1638	    .where(and(eq(gameResultsTable.id, gameResultId), eq(gameResultsTable.status, "pending_verification")))
1639	    .returning();
1640	  if (flipped.length === 0) return; // somebody else already promoted
1641	
1642	  await db.update(gamesTable).set({ status: "completed" }).where(eq(gamesTable.id, result.gameId));
1643	
1644	  const [g] = await db.select().from(gamesTable).where(eq(gamesTable.id, result.gameId));
1645	  if (!g || g.matchType !== "rated") return;
1646	
1647	  const participants = await db.select().from(gameParticipantsTable)
1648	    .where(and(eq(gameParticipantsTable.gameId, g.id), eq(gameParticipantsTable.status, "joined")));
1649	  const teamAPlayers = participants.filter(p => p.team === "A");
1650	  const teamBPlayers = participants.filter(p => p.team === "B");
1651	  const unassigned = participants.filter(p => !p.team);
1652	  const effectiveTeamA = teamAPlayers.length ? teamAPlayers : unassigned.slice(0, Math.ceil(unassigned.length / 2));
1653	  const effectiveTeamB = teamBPlayers.length ? teamBPlayers : unassigned.slice(Math.ceil(unassigned.length / 2));
1654	
1655	  const teamAWithElo = await Promise.all(
1656	    effectiveTeamA.filter(p => p.userId !== null).map(async p => ({ userId: p.userId!, elo: (await getOrCreateRating(p.userId!, g.sport)).elo }))
1657	  );
1658	  const teamBWithElo = await Promise.all(
1659	    effectiveTeamB.filter(p => p.userId !== null).map(async p => ({ userId: p.userId!, elo: (await getOrCreateRating(p.userId!, g.sport)).elo }))
1660	  );
1661	
1662	  const winner: "A" | "B" | "draw" =
1663	    result.scoreTeamA > result.scoreTeamB ? "A" :
1664	    result.scoreTeamB > result.scoreTeamA ? "B" : "draw";
1665	  const changes = calculateTeamElo(teamAWithElo, teamBWithElo, winner);
1666	  const isDraw = winner === "draw";
1667	
1668	  for (const change of changes) {
1669	    const isOnTeamA = !!teamAWithElo.find(p => p.userId === change.userId);
1670	    const isWinner = isDraw ? false : (isOnTeamA ? winner === "A" : winner === "B");
1671	    const winsAdd = isDraw ? 0 : (isWinner ? 1 : 0);
1672	    const lossesAdd = isDraw ? 0 : (!isWinner ? 1 : 0);
1673	    const drawsAdd = isDraw ? 1 : 0;
1674	
1675	    await db.update(userRatingsTable)
1676	      .set({
1677	        elo: change.newElo,
1678	        wins: sql`${userRatingsTable.wins} + ${winsAdd}`,
1679	        losses: sql`${userRatingsTable.losses} + ${lossesAdd}`,
1680	        draws: sql`${userRatingsTable.draws} + ${drawsAdd}`,
1681	        updatedAt: new Date(),
1682	      })
1683	      .where(and(eq(userRatingsTable.userId, change.userId), eq(userRatingsTable.sportSlug, g.sport)));
1684	
1685	    await db.insert(eloHistoryTable).values({
1686	      userId: change.userId,
1687	      sportSlug: g.sport,
1688	      elo: change.newElo,
1689	      delta: change.delta,
1690	      gameId: g.id,
1691	    });
1692	
1693	    const sign = change.delta > 0 ? "+" : "";
1694	    await sendNotification(
1695	      change.userId,
1696	      "elo_update",
