1705	export async function sweepStalePendingGames(): Promise<number> {
1706	  // Find games stuck in pending_payment for > 15 min (Stripe abandoned/expired).
1707	  const stale = await db.select({ id: gamesTable.id, bookingId: gamesTable.bookingId })
1708	    .from(gamesTable)
1709	    .where(and(
1710	      eq(gamesTable.status, "pending_payment"),
1711	      sql`${gamesTable.createdAt} < NOW() - INTERVAL '15 minutes'`,
1712	    ));
1713	  if (stale.length === 0) return 0;
1714	
1715	  for (const row of stale) {
1716	    if (row.bookingId) {
1717	      await db.update(bookingsTable)
1718	        .set({ status: "cancelled" })
1719	        .where(and(eq(bookingsTable.id, row.bookingId), ne(bookingsTable.status, "confirmed")));
1720	    }
1721	    await db.delete(gamesTable).where(and(eq(gamesTable.id, row.id), eq(gamesTable.status, "pending_payment")));
1722	  }
1723	  return stale.length;
1724	}
