131	/** Generate 30-min slots between openTime and closeTime (default: 07:00–22:00).
132	 *  The last slot ends at closeTime, so a slot starting at closeTime is excluded.
133	 *  E.g. open="08:00", close="22:00" produces 08:00–08:30, …, 21:30–22:00
134	 */
135	function generateSlots(openTime = "07:00", closeTime = "22:00"): { startTime: string; endTime: string }[] {
136	  const openMin = timeToMin(openTime);
137	  const closeMin = timeToMin(closeTime);
138	  const slots = [];
139	  for (let m = openMin; m + 30 <= closeMin; m += 30) {
140	    slots.push({ startTime: minToTime(m), endTime: minToTime(m + 30) });
141	  }
142	  return slots;
143	}
