553	
554	  const dayOfWeek = new Date(date + "T00:00:00").getDay();
555	
556	  const [pricingEntries, existingBookings, blockedSlots] = await Promise.all([
557	    db
558	      .select()
559	      .from(courtPricingTable)
560	      .where(
561	        and(
562	          eq(courtPricingTable.courtId, params.data.id),
