13	// GET /messages/inbox  — all threads the authenticated user participated in
14	router.get("/messages/inbox", requireAuth, async (req, res): Promise<void> => {
15	  const { userId } = getAuth(req);
16	
17	  const rows = await db
18	    .select()
19	    .from(messagesTable)
20	    .where(or(eq(messagesTable.senderUserId, userId!), eq(messagesTable.recipientUserId, userId!)))
21	    .orderBy(desc(messagesTable.createdAt));
22	
23	  // Group by courtId — each court is one thread
24	  const threadMap = new Map<number, typeof rows>();
25	  for (const row of rows) {
26	    if (!threadMap.has(row.courtId)) threadMap.set(row.courtId, []);
27	    threadMap.get(row.courtId)!.push(row);
28	  }
29	
30	  const courtIds = [...threadMap.keys()];
31	  const courts = courtIds.length
32	    ? await db.select({ id: courtsTable.id, name: courtsTable.name }).from(courtsTable).where(inArray(courtsTable.id, courtIds))
33	    : [];
34	  const courtNameMap = new Map(courts.map(c => [c.id, c.name]));
35	
36	  const threads = [...threadMap.entries()].map(([courtId, msgs]) => ({
37	    courtId,
38	    courtName: courtNameMap.get(courtId) ?? `Kortas #${courtId}`,
39	    lastMessage: formatMsg(msgs[0]),
40	    unread: 0,
41	  }));
42	
43	  res.json(threads);
44	});
