94	// GET /courts/:id/messages  — all messages in a thread the caller is part of.
95	// Optional ?userId=… narrows to a single owner↔customer thread; only the court
96	// owner is allowed to filter this way (otherwise it would expose other users'
97	// messages on the same court).
98	router.get("/courts/:id/messages", requireAuth, async (req, res): Promise<void> => {
99	  const courtId = Number(req.params.id);
100	  const { userId } = getAuth(req);
101	  if (Number.isNaN(courtId)) {
102	    res.status(400).json({ error: "courtId is required" });
103	    return;
104	  }
105	
106	  const threadUserIdRaw = req.query.userId;
107	  const threadUserId = typeof threadUserIdRaw === "string" ? threadUserIdRaw : undefined;
108	
109	  const [court] = await db.select({ ownerUserId: facilitiesTable.ownerUserId })
110	    .from(courtsTable)
111	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
112	    .where(eq(courtsTable.id, courtId));
113	  const isOwner = !!court && court.ownerUserId === userId;
114	
115	  // Owner asking for a specific thread → only messages between owner and that customer.
116	  if (isOwner && threadUserId) {
117	    const rows = await db
118	      .select()
119	      .from(messagesTable)
120	      .where(and(
121	        eq(messagesTable.courtId, courtId),
122	        or(
123	          and(eq(messagesTable.senderUserId, userId!), eq(messagesTable.recipientUserId, threadUserId)),
124	          and(eq(messagesTable.senderUserId, threadUserId), eq(messagesTable.recipientUserId, userId!)),
125	        ),
126	      ))
127	      .orderBy(messagesTable.createdAt);
128	    res.json(rows.map(formatMsg));
129	    return;
130	  }
131	
132	  // Default: only messages where caller is sender or recipient.
133	  const rows = await db
134	    .select()
135	    .from(messagesTable)
136	    .where(and(eq(messagesTable.courtId, courtId), or(eq(messagesTable.senderUserId, userId!), eq(messagesTable.recipientUserId, userId!))))
137	    .orderBy(messagesTable.createdAt);
138	
139	  res.json(rows.map(formatMsg));
140	});
