145	  const { userId: senderUserId } = getAuth(req);
146	  const { senderName, senderEmail, body, threadUserId } = req.body ?? {};
147	  if (Number.isNaN(courtId) || !senderName || !senderEmail || !body) {
148	    res.status(400).json({ error: "Missing required fields" });
149	    return;
