18	// Compute per-sport game + booking stats for a userId
19	async function computeSportStats(userId: string, email?: string) {
20	  const gameRows = await db
21	    .select({
22	      sport: gamesTable.sport,
23	      gamesPlayed: sql<number>`count(*)`,
24	      minutesPlayed: sql<number>`coalesce(sum(${gamesTable.durationMinutes}), 0)`,
25	    })
26	    .from(gameParticipantsTable)
27	    .innerJoin(gamesTable, eq(gameParticipantsTable.gameId, gamesTable.id))
28	    .where(eq(gameParticipantsTable.userId, userId))
29	    .groupBy(gamesTable.sport);
30	
31	  const sportMap = new Map<string, { gamesPlayed: number; gameHours: number; bookingHours: number }>();
32	  for (const r of gameRows) {
33	    const gameHours = Math.round((Number(r.minutesPlayed) / 60) * 10) / 10;
34	    sportMap.set(r.sport, { gamesPlayed: Number(r.gamesPlayed), gameHours, bookingHours: 0 });
35	  }
36	
37	  if (email) {
38	    const bookingRows = await db
39	      .select({
40	        sport: courtsTable.type,
41	        bookingHours: sql<number>`COALESCE(SUM(EXTRACT(EPOCH FROM (${bookingsTable.endTime}::time - ${bookingsTable.startTime}::time)) / 3600), 0)`,
42	      })
43	      .from(bookingsTable)
44	      .innerJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
45	      .where(and(eq(bookingsTable.customerEmail, email), eq(bookingsTable.status, "confirmed")))
46	      .groupBy(courtsTable.type);
47	
48	    for (const b of bookingRows) {
49	      const bHours = Math.round(Number(b.bookingHours) * 10) / 10;
50	      if (sportMap.has(b.sport)) {
51	        sportMap.get(b.sport)!.bookingHours = bHours;
52	      } else {
53	        sportMap.set(b.sport, { gamesPlayed: 0, gameHours: 0, bookingHours: bHours });
54	      }
55	    }
56	  }
57	
58	  return [...sportMap.entries()].map(([sport, v]) => ({
59	    sport,
60	    gamesPlayed: v.gamesPlayed,
61	    hoursPlayed: Math.round((v.gameHours + v.bookingHours) * 10) / 10,
62	    gameHours: v.gameHours,
63	    bookingHours: v.bookingHours,
64	  }));
65	}
