217	router.get("/admin/users", requireAdmin, async (_req, res): Promise<void> => {
218	  const rows = await db
219	    .select()
220	    .from(userRolesTable)
221	    .orderBy(userRolesTable.createdAt);
222	
223	  if (rows.length === 0) { res.json([]); return; }
224	
225	  // Enrich with Clerk user data (name, email, avatar). Chunk in batches of 100
226	  // because the Clerk SDK caps `limit` at 100 per request.
227	  const userIds = rows.map(r => r.userId);
228	  const clerkUsers: Record<string, { name: string | null; email: string | null; avatarUrl: string | null; lastSignInAt: number | null; clerkCreatedAt: number | null }> = {};
229	  const CHUNK = 100;
230	  for (let i = 0; i < userIds.length; i += CHUNK) {
231	    const chunk = userIds.slice(i, i + CHUNK);
232	    try {
233	      const clerkResp = await clerkClient.users.getUserList({ userId: chunk, limit: CHUNK });
234	      for (const cu of clerkResp.data) {
235	        const name = [cu.firstName, cu.lastName].filter(Boolean).join(" ") || null;
236	        const email = cu.emailAddresses?.[0]?.emailAddress ?? null;
237	        clerkUsers[cu.id] = {
