243	        };
244	      }
245	    } catch {
246	      // If a Clerk call fails, proceed without enrichment for that chunk
247	    }
248	  }
249	
250	  const profiles = userIds.length > 0
251	    ? await db
252	        .select({ userId: userProfilesTable.userId, stripeAccountStatus: userProfilesTable.stripeAccountStatus })
253	        .from(userProfilesTable)
254	        .where(inArray(userProfilesTable.userId, userIds))
255	    : [];
256	  const stripeMap = new Map(profiles.map(p => [p.userId, p.stripeAccountStatus ?? "not_connected"]));
257	
258	  const enriched = rows.map(r => ({
259	    ...r,
260	    name: clerkUsers[r.userId]?.name ?? null,
261	    email: clerkUsers[r.userId]?.email ?? null,
262	    avatarUrl: clerkUsers[r.userId]?.avatarUrl ?? null,
263	    lastSignInAt: clerkUsers[r.userId]?.lastSignInAt ?? null,
264	    clerkCreatedAt: clerkUsers[r.userId]?.clerkCreatedAt ?? null,
265	    stripeAccountStatus: stripeMap.get(r.userId) ?? "not_connected",
266	  }));
267	
268	  res.json(enriched);
269	});
