25	/**
26	 * Source-of-truth readiness check that calls Stripe directly. Returns one of:
27	 *   - { ready: true }            — Stripe says the account is fully ready
28	 *   - { ready: false }           — Stripe says the account is NOT ready
29	 *   - { ready: false, error: … } — Stripe call failed; caller must NOT promote
30	 *
31	 * Used at the verification gate. Fail-closed by design: when we can't reach
32	 * Stripe, we refuse to advance the facility rather than trusting a possibly
33	 * stale cache. The caller surfaces a 503 so the owner retries later.
34	 */
35	async function ownerStripeReadyLive(
36	  userId: string,
37	): Promise<{ ready: boolean; error?: string }> {
38	  const [profile] = await db
39	    .select()
40	    .from(userProfilesTable)
41	    .where(eq(userProfilesTable.userId, userId));
42	  if (!profile?.stripeAccountId) return { ready: false };
43	
44	  try {
45	    const stripe = await getUncachableStripeClient();
46	    const account = await stripe.accounts.retrieve(profile.stripeAccountId);
47	    return { ready: isStripeAccountReady(account) };
48	  } catch (err: any) {
49	    logger.warn({ err, userId }, "ownerStripeReadyLive: Stripe call failed — failing closed");
50	    return { ready: false, error: err?.message ?? "Stripe unreachable" };
51	  }
52	}
