299	/**
300	 * POST /facilities/:id/submit-for-verification
301	 *
302	 * Owner moves a facility from 'draft' into the admin verification queue. The
303	 * gate enforces:
304	 *   - facility data quality (≥3 photos, lat/lng, address)
305	 *   - the OWNER has a fully ready Stripe Connect account
306	 *
307	 * Stripe Connect lives on the owner's profile — a single owner-level connection
308	 * unlocks submission for every draft facility they own. If Stripe is not ready
309	 * we refuse the transition with 422 and leave the facility in 'draft'.
310	 */
311	router.post("/facilities/:id/submit-for-verification", requireAuth, async (req, res): Promise<void> => {
312	  const userId = getCurrentUserId(req);
313	  if (!userId) { res.status(401).json({ error: "Unauthorized" }); return; }
314	  const id = parseInt(String(req.params.id), 10);
315	  if (isNaN(id)) { res.status(400).json({ error: "Invalid facility ID" }); return; }
316	
317	  const [facility] = await db.select().from(facilitiesTable).where(eq(facilitiesTable.id, id));
318	  if (!facility) { res.status(404).json({ error: "Facility not found" }); return; }
319	  if (!(await isOwner(req, facility.ownerUserId))) {
320	    res.status(403).json({ error: "Forbidden" }); return;
321	  }
322	
323	  if (facility.verificationStatus === "active") {
324	    res.status(400).json({ error: "Objektas jau aktyvus." });
325	    return;
326	  }
327	  if (facility.verificationStatus === "pending_verification") {
328	    res.status(400).json({ error: "Objektas jau laukia patvirtinimo." });
329	    return;
330	  }
331	  if (facility.verificationStatus === "suspended") {
332	    res.status(400).json({ error: "Objektas sustabdytas — kreipkitės į administratorių." });
333	    return;
334	  }
335	
336	  const issues = validateForVerification(facility);
337	  if (issues.length > 0) {
338	    res.status(400).json({
339	      error: "Trūksta privalomų duomenų prieš pateikiant patvirtinimui.",
340	      issues,
341	    });
342	    return;
343	  }
344	
345	  // Owner-level Stripe gate — single source of truth. Live re-check against
346	  // Stripe so a missed webhook can't block the owner indefinitely, and a stale
347	  // cache can't promote past the gate.
348	  const liveResult = await ownerStripeReadyLive(userId);
349	  if (liveResult.error) {
350	    res.status(503).json({
351	      error: "Nepavyko pasiekti Stripe paslaugos. Bandykite dar kartą po kelių sekundžių.",
352	    });
353	    return;
354	  }
355	  if (!liveResult.ready) {
356	    // Sync the cached owner status before refusing so the UI can react.
357	    await db
358	      .update(userProfilesTable)
359	      .set({ stripeAccountStatus: "pending" })
360	      .where(eq(userProfilesTable.userId, userId));
361	    res.status(422).json({
362	      error: "Prijunkite Stripe Connect prieš teikdami objektą patvirtinimui.",
363	      code: "stripe_not_connected",
364	    });
365	    return;
366	  }
367	
368	  // Compare-and-set: only mutate if the row is STILL in the status we read.
369	  const [updated] = await db
370	    .update(facilitiesTable)
371	    .set({
372	      verificationStatus: "pending_verification",
373	      verificationNotes: null,
374	      rejectionReason: null,
375	    })
376	    .where(and(
377	      eq(facilitiesTable.id, id),
378	      eq(facilitiesTable.verificationStatus, facility.verificationStatus),
379	    ))
380	    .returning();
381	
382	  if (!updated) {
383	    res.status(409).json({
384	      error: "Objekto būsena pasikeitė. Atnaujinkite puslapį ir bandykite dar kartą.",
385	    });
386	    return;
387	  }
388	
389	  await sendAdminNotification(
390	    "Objektas laukia patvirtinimo",
391	    `„${updated.name}" (${updated.city ?? "—"}) pateiktas peržiūrai.`,
392	    "/admin",
393	  );
394	
395	  res.json({
396	    id: updated.id,
397	    verificationStatus: updated.verificationStatus,
398	  });
399	});
