419	  // cascade-delete dependent rows that don't have a DB-level FK constraint
420	  // (court_pricing, reviews, bookings, games), as well as those that do but
421	  // would otherwise be orphaned because facilities → courts is ON DELETE SET NULL.
422	  const facilityCourts = await db
423	    .select({ id: courtsTable.id })
424	    .from(courtsTable)
425	    .where(eq(courtsTable.facilityId, params.data.id));
426	  const courtIds = facilityCourts.map((c) => c.id);
427	
428	  // Safety guard: refuse to delete if there are upcoming PAID bookings that
429	  // would be silently dropped. The owner must refund/cancel them first.
430	  if (courtIds.length > 0) {
431	    const today = new Date().toISOString().slice(0, 10);
432	    const [{ count: futurePaid } = { count: 0 }] = await db
433	      .select({ count: sql<number>`count(*)::int` })
434	      .from(bookingsTable)
435	      .where(
436	        and(
437	          inArray(bookingsTable.courtId, courtIds),
438	          gte(bookingsTable.date, today),
439	          eq(bookingsTable.status, "paid"),
440	        ),
441	      );
442	    if (futurePaid > 0) {
443	      res.status(409).json({
444	        error: `Negalima ištrinti: yra ${futurePaid} būsimų apmokėtų rezervacijų. Pirmiausia jas atšaukite ir grąžinkite pinigus.`,
445	      });
446	      return;
447	    }
448	  }
449	
450	  // Manual cascade in a transaction. Order matters:
451	  //  1) Delete leaf rows that reference courts/facility without an FK.
452	  //  2) Delete the courts (DB CASCADE handles court_blocked_slots,
453	  //     court_coaches, court_photos, tournaments(court_id),
454	  //     court_memberships, user_memberships, court_coach_invitations).
455	  //  3) Delete the facility itself.
456	  await db.transaction(async (tx) => {
457	    if (courtIds.length > 0) {
458	      await tx.delete(reviewsTable).where(inArray(reviewsTable.courtId, courtIds));
459	      await tx.delete(courtPricingTable).where(inArray(courtPricingTable.courtId, courtIds));
460	      await tx.delete(bookingsTable).where(inArray(bookingsTable.courtId, courtIds));
461	      await tx
