1	/**
2	 * Stripe webhook endpoint — POST /api/webhooks/stripe
3	 *
4	 * Receives the raw request body and verifies the Stripe-Signature header
5	 * using STRIPE_WEBHOOK_SECRET. Handles the events relevant to the marketplace:
6	 *   - checkout.session.completed       → mark booking as confirmed/pending
7	 *   - checkout.session.async_payment_succeeded
8	 *   - account.updated                  → keep our cached Connect status in sync
9	 *
10	 * This route is registered in app.ts BEFORE express.json() so the body stays
11	 * a Buffer (required by stripe.webhooks.constructEvent).
12	 */
13	import type { Request, Response } from "express";
14	import type Stripe from "stripe";
15	import { randomBytes } from "node:crypto";
16	import { eq, and, ne, sql } from "drizzle-orm";
17	import {
18	  db,
19	  bookingsTable,
20	  courtsTable,
21	  facilitiesTable,
22	  userProfilesTable,
23	  gamesTable,
24	  gameParticipantsTable,
25	} from "@workspace/db";
26	import { getStripe, getStripeWebhookSecret } from "../stripeClient";
27	import { logger } from "../lib/logger";
28	import {
29	  sendBookingConfirmationEmail,
30	  sendOwnerBookingNotificationEmail,
31	  sendSplitPlayerJoinedEmail,
32	  sendSplitParticipantConfirmationEmail,
33	} from "../lib/email";
34	import { sendNotification, sendAdminNotification } from "../lib/notify";
35	import { isStripeAccountReady } from "../lib/facility-status";
