105	async function handleCheckoutCompleted(session: Stripe.Checkout.Session): Promise<void> {
106	  if (session.payment_status !== "paid") return;
107	
108	  // ── 1. Try to find a booking by stripeSessionId (covers regular and split-host payments) ──
109	  const rows = await db
110	    .select({
111	      booking: bookingsTable,
112	      courtName: courtsTable.name,
113	      courtId: courtsTable.id,
114	      courtAddress: facilitiesTable.address,
115	      courtCity: facilitiesTable.city,
116	      courtPhone: courtsTable.phone,
117	      courtImageUrl: courtsTable.imageUrl,
118	      ownerName: facilitiesTable.companyName,
119	      ownerEmail: facilitiesTable.email,
120	      instantBookingEnabled: courtsTable.instantBookingEnabled,
121	      hasSmartLock: courtsTable.hasSmartLock,
122	    })
123	    .from(bookingsTable)
124	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
125	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
126	    .where(eq(bookingsTable.stripeSessionId, session.id));
127	
128	  if (rows[0]) {
129	    const booking = rows[0].booking;
130	
131	    if (booking.isSplit) {
132	      // ── Split booking: this is the HOST's first payment ──────────────────
133	      // CAS: pending → awaiting_players (reserves the court slot)
134	      const updatedRows = await db
135	        .update(bookingsTable)
136	        .set({ status: "awaiting_players" })
137	        .where(and(
138	          eq(bookingsTable.stripeSessionId, session.id),
139	          eq(bookingsTable.status, "pending"),
140	        ))
141	        .returning();
142	
143	      if (updatedRows.length === 0) {
144	        // Already processed (awaiting_players or confirmed). Still mark participant paid.
145	      }
146	
147	      // Mark host participant as paid
148	      await db
149	        .update(gameParticipantsTable)
150	        .set({ paymentStatus: "paid" })
151	        .where(eq(gameParticipantsTable.stripeSessionId, session.id));
152	
153	      // Update game to awaiting_players
154	      await db
155	        .update(gamesTable)
156	        .set({ status: "awaiting_players" })
157	        .where(and(
158	          eq(gamesTable.bookingId, booking.id),
159	          eq(gamesTable.status, "pending_payment"),
160	        ));
161	
162	      // Check if somehow all slots are already paid (edge case: totalSlots=1)
163	      await maybeConfirmSplitBooking(booking.id, rows[0]);
164	      return;
165	    }
166	
167	    // ── Regular (non-split) booking ──────────────────────────────────────────
168	    // If the confirm endpoint already promoted the booking, do nothing else.
169	    if (booking.status === "confirmed") return;
170	
171	    // CAS guard: only promote if booking is still pending.
172	    const updatedRows = await db
173	      .update(bookingsTable)
174	      .set({ status: "confirmed" })
175	      .where(and(
176	        eq(bookingsTable.stripeSessionId, session.id),
177	        eq(bookingsTable.status, "pending"),
178	      ))
179	      .returning();
180	
181	    if (updatedRows.length === 0) {
182	      logger.warn(
183	        { sessionId: session.id, bookingId: booking.id, currentStatus: booking.status },
184	        "Webhook: stale checkout.session.completed — booking no longer pending, ignoring",
185	      );
186	      return;
187	    }
188	    const confirmedBooking = updatedRows[0]!;
189	
190	    await db
191	      .update(courtsTable)
192	      .set({ totalBookings: sql`total_bookings + 1` })
193	      .where(eq(courtsTable.id, rows[0].booking.courtId));
194	
195	    // Generate a smart-lock access code if the court has a smart lock
196	    let smartAccessCode: string | undefined;
197	    if (rows[0].hasSmartLock) {
198	      smartAccessCode = randomBytes(3).toString("hex").toUpperCase(); // 6-char hex e.g. "A3F9C1"
199	      await db
200	        .update(bookingsTable)
201	        .set({ accessCode: smartAccessCode })
202	        .where(eq(bookingsTable.id, confirmedBooking.id));
203	    }
204	
205	    sendBookingConfirmationEmail({
206	      customerName: confirmedBooking.customerName,
207	      customerEmail: confirmedBooking.customerEmail,
208	      courtName: rows[0].courtName ?? "Kortas",
209	      courtId: rows[0].courtId ?? 0,
210	      courtAddress: rows[0].courtAddress ?? "",
211	      courtCity: rows[0].courtCity ?? "",
212	      courtPhone: rows[0].courtPhone ?? undefined,
213	      courtImageUrl: rows[0].courtImageUrl ?? undefined,
214	      date: confirmedBooking.date,
215	      startTime: confirmedBooking.startTime,
216	      endTime: confirmedBooking.endTime,
217	      totalPrice: Number(confirmedBooking.totalPrice),
218	      bookingId: confirmedBooking.id,
219	      accessCode: smartAccessCode,
220	    }).catch((err) => logger.error({ err }, "sendBookingConfirmationEmail (webhook) failed"));
221	
222	    if (rows[0].ownerEmail) {
223	      sendOwnerBookingNotificationEmail({
224	        ownerName: rows[0].ownerName ?? "Savininkas",
225	        ownerEmail: rows[0].ownerEmail,
226	        customerName: confirmedBooking.customerName,
227	        courtName: rows[0].courtName ?? "Kortas",
228	        date: confirmedBooking.date,
229	        startTime: confirmedBooking.startTime,
230	        endTime: confirmedBooking.endTime,
231	        totalPrice: Number(confirmedBooking.totalPrice),
232	        bookingId: confirmedBooking.id,
233	      }).catch((err) => logger.error({ err }, "sendOwnerBookingNotificationEmail (webhook) failed"));
234	    }
235	
236	    // Host-Pays-All: if a game is linked to this booking, flip it from pending_payment → open.
237	    await db
238	      .update(gamesTable)
239	      .set({ status: "open" })
240	      .where(and(eq(gamesTable.bookingId, confirmedBooking.id), eq(gamesTable.status, "pending_payment")));
241	
242	    return;
243	  }
244	
245	  // ── 2. No booking matched by stripeSessionId — try split participant lookup ──
246	  const [participant] = await db
247	    .select()
248	    .from(gameParticipantsTable)
249	    .where(eq(gameParticipantsTable.stripeSessionId, session.id));
250	
251	  if (!participant) {
252	    logger.warn({ sessionId: session.id }, "Webhook: no booking or participant matched session");
253	    return;
254	  }
255	
256	  // Mark this participant as paid (CAS: only if still pending)
257	  const updatedParticipants = await db
258	    .update(gameParticipantsTable)
259	    .set({ paymentStatus: "paid" })
260	    .where(and(
261	      eq(gameParticipantsTable.stripeSessionId, session.id),
262	      eq(gameParticipantsTable.paymentStatus, "pending"),
263	    ))
264	    .returning();
265	
266	  if (updatedParticipants.length === 0) {
267	    logger.debug({ sessionId: session.id }, "Webhook: split participant already paid, idempotent skip");
268	    return;
269	  }
270	
271	  const paidParticipant = updatedParticipants[0]!;
272	
273	  // Get game → booking context
274	  const [game] = await db.select().from(gamesTable).where(eq(gamesTable.id, participant.gameId));
275	  if (!game?.bookingId) {
276	    logger.warn({ participantId: participant.id }, "Webhook: split participant has no linked game/booking");
277	    return;
278	  }
279	
280	  const bookingRows = await db
281	    .select({
282	      booking: bookingsTable,
283	      courtName: courtsTable.name,
284	      courtId: courtsTable.id,
285	      courtAddress: facilitiesTable.address,
286	      courtCity: facilitiesTable.city,
287	      courtPhone: courtsTable.phone,
288	      courtImageUrl: courtsTable.imageUrl,
289	      ownerName: facilitiesTable.companyName,
290	      ownerEmail: facilitiesTable.email,
291	    })
292	    .from(bookingsTable)
293	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
294	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
295	    .where(eq(bookingsTable.id, game.bookingId));
296	
297	  if (!bookingRows[0]) {
298	    logger.warn({ bookingId: game.bookingId }, "Webhook: split booking not found");
299	    return;
300	  }
301	
302	  // Count paid slots for notification content
303	  const paidCountRows = await db
304	    .select({ count: sql<string>`count(*)` })
305	    .from(gameParticipantsTable)
306	    .where(and(
307	      eq(gameParticipantsTable.gameId, game.id),
308	      eq(gameParticipantsTable.status, "joined"),
309	      eq(gameParticipantsTable.paymentStatus, "paid"),
310	    ));
311	  const paidCount = parseInt(paidCountRows[0]?.count ?? "0", 10);
312	  const { booking, courtName } = bookingRows[0];
313	  const playerName = paidParticipant.userName ?? paidParticipant.userEmail ?? "Žaidėjas";
314	
315	  // Notify host that a new player joined/paid
316	  if (booking.bookerUserId) {
317	    sendNotification(
318	      booking.bookerUserId,
319	      "split_player_joined",
320	      `${playerName} prisijungė prie jūsų žaidimo!`,
321	      `Apmokėta: ${paidCount}/${booking.totalSlots ?? 1} vietų – ${courtName ?? "kortas"}, ${booking.date}`,
322	      `/bookings/${booking.id}`,
323	    ).catch(() => {});
324	
325	    sendSplitPlayerJoinedEmail({
326	      hostName: booking.customerName,
327	      hostEmail: booking.customerEmail,
328	      playerName,
329	      courtName: courtName ?? "Kortas",
330	      date: booking.date,
331	      startTime: booking.startTime,
332	      endTime: booking.endTime,
333	      paidSlots: paidCount,
334	      totalSlots: booking.totalSlots ?? 1,
335	      bookingId: booking.id,
336	    }).catch((err) => logger.error({ err }, "sendSplitPlayerJoinedEmail (webhook) failed"));
337	  }
338	
339	  // Send confirmation email to the participant
340	  if (paidParticipant.userEmail) {
341	    sendSplitParticipantConfirmationEmail({
342	      playerName,
343	      playerEmail: paidParticipant.userEmail,
344	      courtName: courtName ?? "Kortas",
345	      courtId: bookingRows[0].courtId ?? booking.courtId,
346	      date: booking.date,
347	      startTime: booking.startTime,
348	      endTime: booking.endTime,
349	      pricePerSlot: Number(booking.pricePerSlot ?? 0),
350	      bookingId: booking.id,
351	    }).catch((err) => logger.error({ err }, "sendSplitParticipantConfirmationEmail (webhook) failed"));
352	  }
353	
354	  await maybeConfirmSplitBooking(game.bookingId, bookingRows[0]);
355	}
