357	// ─── maybeConfirmSplitBooking ─────────────────────────────────────────────────
358	// Called after any split participant pays. If all slots are now paid, confirms
359	// the booking and opens the game.
360	async function maybeConfirmSplitBooking(
361	  bookingId: number,
362	  context: {
363	    booking: typeof bookingsTable.$inferSelect;
364	    courtName: string | null;
365	    courtId: number | null;
366	    courtAddress: string | null;
367	    courtCity: string | null;
368	    courtPhone: string | null;
369	    courtImageUrl: string | null;
370	    ownerName: string | null;
371	    ownerEmail: string | null;
372	  },
373	): Promise<void> {
374	  const { booking } = context;
375	  if (!booking.totalSlots) return;
376	
377	  const [game] = await db.select().from(gamesTable).where(eq(gamesTable.bookingId, bookingId));
378	  if (!game) return;
379	
380	  const paidRows = await db
381	    .select({ count: sql<string>`count(*)` })
382	    .from(gameParticipantsTable)
383	    .where(and(
384	      eq(gameParticipantsTable.gameId, game.id),
385	      eq(gameParticipantsTable.status, "joined"),
386	      eq(gameParticipantsTable.paymentStatus, "paid"),
387	    ));
388	
389	  const paidCount = parseInt(paidRows[0]?.count ?? "0", 10);
390	
391	  if (paidCount < booking.totalSlots) {
392	    logger.info(
393	      { bookingId, paidCount, totalSlots: booking.totalSlots },
394	      "Split payment: waiting for more players",
395	    );
396	    return;
397	  }
398	
399	  // All slots paid — confirm the booking
400	  const confirmed = await db
401	    .update(bookingsTable)
402	    .set({ status: "confirmed" })
403	    .where(and(
404	      eq(bookingsTable.id, bookingId),
405	      ne(bookingsTable.status, "confirmed"),
406	    ))
407	    .returning();
408	
409	  if (confirmed.length === 0) {
410	    logger.debug({ bookingId }, "Split booking already confirmed (idempotent)");
411	    return;
412	  }
413	
414	  // Open the game
415	  await db
416	    .update(gamesTable)
417	    .set({ status: "open" })
418	    .where(eq(gamesTable.id, game.id));
419	
420	  // Increment court booking count
421	  await db
422	    .update(courtsTable)
423	    .set({ totalBookings: sql`total_bookings + 1` })
424	    .where(eq(courtsTable.id, booking.courtId));
425	
426	  logger.info({ bookingId, paidCount }, "Split booking fully paid — confirmed");
427	
428	  // Notify host that all slots are filled
429	  if (booking.bookerUserId) {
430	    sendNotification(
431	      booking.bookerUserId,
432	      "split_player_joined",
433	      "Visi žaidėjai sumokėjo! 🎉",
434	      `Jūsų rezervacija ${context.courtName ?? "kortas"} (${booking.date}) patvirtinta — visi ${booking.totalSlots} žaidėjai apmokėję.`,
435	      `/bookings/${bookingId}`,
436	    ).catch(() => {});
437	  }
438	
439	  // Send confirmation email to the host (booker)
440	  sendBookingConfirmationEmail({
441	    customerName: booking.customerName,
442	    customerEmail: booking.customerEmail,
443	    courtName: context.courtName ?? "Kortas",
444	    courtId: context.courtId ?? 0,
445	    courtAddress: context.courtAddress ?? "",
446	    courtCity: context.courtCity ?? "",
447	    courtPhone: context.courtPhone ?? undefined,
448	    courtImageUrl: context.courtImageUrl ?? undefined,
449	    date: booking.date,
450	    startTime: booking.startTime,
451	    endTime: booking.endTime,
452	    totalPrice: Number(booking.totalPrice),
453	    bookingId: booking.id,
454	  }).catch((err) => logger.error({ err }, "sendBookingConfirmationEmail (split confirm) failed"));
455	
456	  if (context.ownerEmail) {
457	    sendOwnerBookingNotificationEmail({
458	      ownerName: context.ownerName ?? "Savininkas",
459	      ownerEmail: context.ownerEmail,
460	      customerName: booking.customerName,
461	      courtName: context.courtName ?? "Kortas",
462	      date: booking.date,
463	      startTime: booking.startTime,
464	      endTime: booking.endTime,
465	      totalPrice: Number(booking.totalPrice),
466	      bookingId: booking.id,
467	    }).catch((err) => logger.error({ err }, "sendOwnerBookingNotificationEmail (split) failed"));
468	  }
469	}
