471	async function handleCheckoutExpired(session: Stripe.Checkout.Session): Promise<void> {
472	  // Find the booking by stripeSessionId; if it's still pending, cancel it and delete any linked pending game.
473	  const [booking] = await db
474	    .select()
475	    .from(bookingsTable)
476	    .where(eq(bookingsTable.stripeSessionId, session.id));
477	
478	  if (booking) {
479	    // Only cancel if still pending — never disturb confirmed/awaiting_players bookings.
480	    await db
481	      .update(bookingsTable)
482	      .set({ status: "cancelled" })
483	      .where(and(eq(bookingsTable.id, booking.id), eq(bookingsTable.status, "pending")));
484	
485	    await db
486	      .delete(gamesTable)
487	      .where(and(eq(gamesTable.bookingId, booking.id), eq(gamesTable.status, "pending_payment")));
488	
489	    logger.info({ bookingId: booking.id, sessionId: session.id }, "stripe webhook: expired session — released hold");
490	    return;
491	  }
492	
493	  // Also handle expired split-participant sessions: remove the pending participant
494	  const [participant] = await db
495	    .select()
496	    .from(gameParticipantsTable)
497	    .where(eq(gameParticipantsTable.stripeSessionId, session.id));
498	
499	  if (participant && participant.paymentStatus === "pending") {
500	    await db
501	      .delete(gameParticipantsTable)
502	      .where(and(
503	        eq(gameParticipantsTable.id, participant.id),
504	        eq(gameParticipantsTable.paymentStatus, "pending"),
505	      ));
506	    logger.info({ participantId: participant.id }, "stripe webhook: expired split participant session — removed slot hold");
507	  }
508	}
