510	async function handleAccountUpdated(account: Stripe.Account): Promise<void> {
511	  const stripeComplete = isStripeAccountReady(account);
512	  logger.info(
513	    {
514	      accountId: account.id,
515	      detailsSubmitted: account.details_submitted,
516	      chargesEnabled: account.charges_enabled,
517	      payoutsEnabled: account.payouts_enabled,
518	      disabledReason: account.requirements?.disabled_reason ?? null,
519	      stripeComplete,
520	    },
521	    "stripe webhook: account.updated",
522	  );
523	  const newStatus = stripeComplete ? "active" : "pending";
524	
525	  // Owner profile is the single source of truth for Stripe readiness — payment
526	  // and submission flows read it directly. There is no per-facility cascade.
527	  const [profile] = await db
528	    .update(userProfilesTable)
529	    .set({ stripeAccountStatus: newStatus })
530	    .where(eq(userProfilesTable.stripeAccountId, account.id))
531	    .returning({ userId: userProfilesTable.userId, prevStatus: userProfilesTable.stripeAccountStatus });
532	
533	  if (!profile) return;
534	
535	  // Notify the owner so they're aware their account regressed and any new
536	  // bookings won't go through until they re-complete Stripe.
537	  if (!stripeComplete) {
538	    await sendNotification(
539	      profile.userId,
540	      "facility_rejected",
541	      "Reikia atnaujinti Stripe duomenis",
542	      "Stripe pranešė apie trūkstamą informaciją. Atnaujinkite duomenis, kad galėtumėte priimti mokėjimus.",
543	      `/owner`,
544	    ).catch(() => {});
545	  }
546	}
