11	// Convert a UTC instant to the Vilnius wall-clock representation that we store
12	// in `bookings.date` and `bookings.startTime`.
13	function utcMsToVilniusLocal(ms: number): { date: string; time: string } {
14	  const fmt = new Intl.DateTimeFormat("en-GB", {
15	    timeZone: "Europe/Vilnius",
16	    year: "numeric", month: "2-digit", day: "2-digit",
17	    hour: "2-digit", minute: "2-digit",
18	    hour12: false,
19	  });
20	  const parts = fmt.formatToParts(new Date(ms));
21	  const get = (t: string) => parts.find(p => p.type === t)!.value;
22	  let hh = get("hour");
23	  if (hh === "24") hh = "00";
24	  return {
25	    date: `${get("year")}-${get("month")}-${get("day")}`,
26	    time: `${hh}:${get("minute")}`,
27	  };
28	}
29	
30	function addMinutes(time: string, mins: number): string {
31	  const [h, m] = time.split(":").map(Number);
32	  const total = (h * 60 + m + mins + 24 * 60) % (24 * 60);
33	  const nh = Math.floor(total / 60);
34	  const nm = total % 60;
35	  return `${String(nh).padStart(2, "0")}:${String(nm).padStart(2, "0")}`;
36	}
