27	router.post("/courts/:id/reviews", async (req, res): Promise<void> => {
28	  const courtId = parseInt(req.params.id, 10);
29	  if (isNaN(courtId)) {
30	    res.status(400).json({ error: "Invalid court id" });
31	    return;
32	  }
33	
34	  const { bookingId, rating, reviewText, reviewerName, photos } = req.body;
35	
36	  if (!bookingId || !rating || !reviewerName) {
37	    res.status(400).json({ error: "bookingId, rating, and reviewerName are required" });
38	    return;
39	  }
40	
41	  if (typeof rating !== "number" || rating < 1 || rating > 5) {
42	    res.status(400).json({ error: "rating must be a number between 1 and 5" });
43	    return;
44	  }
45	
46	  // Verify booking exists and belongs to this court
47	  const [booking] = await db
48	    .select()
49	    .from(bookingsTable)
50	    .where(and(eq(bookingsTable.id, bookingId), eq(bookingsTable.courtId, courtId)));
51	
52	  if (!booking) {
53	    res.status(404).json({ error: "Booking not found or does not belong to this court" });
54	    return;
55	  }
56	
57	  if (booking.status !== "confirmed") {
58	    res.status(400).json({ error: "Only confirmed bookings can be reviewed" });
59	    return;
60	  }
61	
62	  // Check if this booking already has a review
63	  const [existing] = await db
64	    .select()
65	    .from(reviewsTable)
66	    .where(eq(reviewsTable.bookingId, bookingId));
67	
68	  if (existing) {
69	    res.status(400).json({ error: "This booking has already been reviewed" });
70	    return;
71	  }
72	
73	  // Validate and serialize photos
74	  const photoUrls: string[] = Array.isArray(photos) ? photos.slice(0, 3) : [];
75	
76	  // Insert review
77	  const [review] = await db
78	    .insert(reviewsTable)
79	    .values({
80	      courtId,
81	      bookingId,
82	      rating,
83	      reviewText: reviewText || null,
84	      reviewerName,
85	      photos: photoUrls.length > 0 ? JSON.stringify(photoUrls) : null,
86	    })
87	    .returning();
88	
89	  // Update court's average rating
90	  const result = await db
91	    .select({ avg: avg(reviewsTable.rating) })
92	    .from(reviewsTable)
93	    .where(eq(reviewsTable.courtId, courtId));
94	
95	  const avgRating = result[0]?.avg ? parseFloat(result[0].avg) : null;
96	
97	  if (avgRating !== null) {
98	    await db
99	      .update(courtsTable)
100	      .set({ rating: avgRating })
101	      .where(eq(courtsTable.id, courtId));
102	  }
103	
104	  res.status(201).json({
105	    ...review,
106	    reviewText: review.reviewText ?? undefined,
107	    createdAt: review.createdAt.toISOString(),
108	  });
109	});
